_TEXT = {}


def text(value):
    """Lowercase compressed spelling of an address integer (memoised)."""
    spelling = _TEXT.get(value)
    if spelling is None:
        spelling = str(ipaddress.IPv6Address(value))
        _TEXT[value] = spelling
    return spelling


def addresses(values):
    """Distinct, numerically increasing address texts for an iterable of ints."""
    return [text(n) for n in sorted(set(values))]
